<?php require_once 'layout.php'; require_admin(); $users=db()->query("SELECT id,full_name,email,phone,created_at FROM users WHERE role='user' ORDER BY id DESC"); page_header('Users',true); ?><h1>Users</h1><div class="cart-box"><table><tr><th>Name</th><th>Email</th><th>Phone</th><th>Joined</th></tr><?php while($u=$users->fetch_assoc()):?><tr><td><?=h($u['full_name'])?></td><td><?=h($u['email'])?></td><td><?=h($u['phone'])?></td><td><?=date('d M Y',strtotime($u['created_at']))?></td></tr><?php endwhile;?></table></div><?php page_footer(); ?>
